// Free-field microphone-array baseline. See array-method.md for equations and scope.
export const FS=48000, N=512, H=128, M=4;
export const GEOMETRY=[[-.09,.008],[-.09,-.008],[.09,.008],[.09,-.008]];
export const now=()=>globalThis.performance?.now?.() ?? NaN;
export function bytes(value,seen=new Set()) {if(!value||typeof value!=='object')return 0;if(ArrayBuffer.isView(value)){if(seen.has(value.buffer))return 0;seen.add(value.buffer);return value.buffer.byteLength;}if(seen.has(value))return 0;seen.add(value);return Object.values(value).reduce((s,v)=>s+bytes(v,seen),0);}
export class Timer {
 constructor(){this.series={};this.last={};}
 add(name,start){const v=now()-start;if(!Number.isFinite(v))return;let s=this.series[name];if(!s)s=this.series[name]={data:new Float64Array(2048),n:0};s.data[s.n++%s.data.length]=v;this.last[name]=v;}
 report(){return Object.fromEntries(Object.entries(this.series).map(([k,s])=>{const a=Array.from(s.data.subarray(0,Math.min(s.n,s.data.length))).sort((a,b)=>a-b);return[k,{calls:s.n,p50_ms:a[Math.floor(a.length*.5)],p95_ms:a[Math.floor(a.length*.95)],p99_ms:a[Math.floor(a.length*.99)],max_ms:a.at(-1)}];}));}
}
export class FFT {
 constructor(n=N){this.n=n;this.rev=new Uint16Array(n);this.cos=new Float64Array(n/2);this.sin=new Float64Array(n/2);for(let i=0;i<n;i++){let x=i,r=0;for(let b=0;b<Math.log2(n);b++){r=(r<<1)|(x&1);x>>=1;}this.rev[i]=r;}for(let i=0;i<n/2;i++){this.cos[i]=Math.cos(2*Math.PI*i/n);this.sin[i]=Math.sin(2*Math.PI*i/n);}}
 run(r,im,inverse=false){const n=this.n;for(let i=0;i<n;i++){let j=this.rev[i];if(j>i){[r[i],r[j]]=[r[j],r[i]];[im[i],im[j]]=[im[j],im[i]];}}for(let size=2;size<=n;size*=2){let half=size/2,step=n/size;for(let base=0;base<n;base+=size)for(let j=0;j<half;j++){let c=this.cos[j*step],s=(inverse?1:-1)*this.sin[j*step],b=base+j+half,a=base+j,tr=c*r[b]-s*im[b],ti=c*im[b]+s*r[b];r[b]=r[a]-tr;im[b]=im[a]-ti;r[a]+=tr;im[a]+=ti;}}if(inverse)for(let i=0;i<n;i++){r[i]/=n;im[i]/=n;}}
}
export function delays(angle){let a=angle*Math.PI/180;return GEOMETRY.map(([x,y])=>24-(x*Math.sin(a)+y*Math.cos(a))*FS/343);}
export function steering(angle,k){return delays(angle).map(d=>{let n=Math.floor(d),f=d-n,w=2*Math.PI*k/N;return[(1-f)*Math.cos(w*n)+f*Math.cos(w*(n+1)),-(1-f)*Math.sin(w*n)-f*Math.sin(w*(n+1))];});}
export class Scene {
 constructor(){this.hist=[new Float64Array(128),new Float64Array(128)];this.p=0;this.pos=[0,0];this.sources=[null,null];this.seed=20261125;this.smooth=0;this.configure({target:0,masker:90,head:0,snr:0,noise:'noise'});}
 configure(c){Object.assign(this,c);this.ds=[delays(this.target-this.head),delays(this.masker-this.head)];}
 process(out,calibrating=false){for(let i=0;i<out[0].length;i++){let s=this.sources[0],t=s?s[this.pos[0]++%s.length]:0;this.seed=(Math.imul(1664525,this.seed)+1013904223)>>>0;this.smooth=.85*this.smooth+.15*(this.seed/2147483648-1);let n=this.sources[1];n=this.noise==='speech'&&n?n[this.pos[1]++%n.length]:this.smooth*.304;this.hist[0][this.p]=calibrating?0:t;this.hist[1][this.p]=n*10**(-this.snr/20);for(let m=0;m<M;m++){let v=0;for(let j=0;j<2;j++){let d=this.ds[j][m],b=Math.floor(d),f=d-b;v+=(1-f)*this.hist[j][(this.p-b+128)%128]+f*this.hist[j][(this.p-b-1+128)%128];}out[m][i]=v;}this.p=(this.p+1)%128;}}
}
// Complex Gaussian elimination, fixed four-microphone matrix. Work storage reused.
export function solve(ar,ai,br,bi,xr,xi){for(let c=0;c<M;c++){let pivot=c,best=0;for(let r=c;r<M;r++){let j=r*M+c,q=ar[j]**2+ai[j]**2;if(q>best){best=q;pivot=r;}}if(best<1e-30)return false;if(pivot!==c){for(let k=c;k<M;k++){let a=c*M+k,b=pivot*M+k;[ar[a],ar[b]]=[ar[b],ar[a]];[ai[a],ai[b]]=[ai[b],ai[a]];}[br[c],br[pivot]]=[br[pivot],br[c]];[bi[c],bi[pivot]]=[bi[pivot],bi[c]];}for(let r=c+1;r<M;r++){let j=r*M+c,p=c*M+c,d=ar[p]**2+ai[p]**2,fr=(ar[j]*ar[p]+ai[j]*ai[p])/d,fi=(ai[j]*ar[p]-ar[j]*ai[p])/d;for(let k=c;k<M;k++){let a=r*M+k,b=c*M+k;ar[a]-=fr*ar[b]-fi*ai[b];ai[a]-=fr*ai[b]+fi*ar[b];}br[r]-=fr*br[c]-fi*bi[c];bi[r]-=fr*bi[c]+fi*br[c];}}
 for(let r=M-1;r>=0;r--){let re=br[r],im=bi[r];for(let k=r+1;k<M;k++){re-=ar[r*M+k]*xr[k]-ai[r*M+k]*xi[k];im-=ar[r*M+k]*xi[k]+ai[r*M+k]*xr[k];}let p=r*M+r,d=ar[p]**2+ai[p]**2;xr[r]=(re*ar[p]+im*ai[p])/d;xi[r]=(im*ar[p]-re*ai[p])/d;}return xr.every(Number.isFinite)&&xi.every(Number.isFinite);}
export class Beamformer {
 constructor(timer=new Timer()){this.timer=timer;this.fft=new FFT();this.history=Array.from({length:M},()=>new Float64Array(N));this.xr=Array.from({length:M},()=>new Float64Array(N));this.xi=Array.from({length:M},()=>new Float64Array(N));this.yr=[new Float64Array(N),new Float64Array(N)];this.yi=[new Float64Array(N),new Float64Array(N)];this.ola=[new Float64Array(2*N),new Float64Array(2*N)];this.window=Float64Array.from({length:N},(_,i)=>Math.sqrt(.5-.5*Math.cos(2*Math.PI*i/N)));this.rr=new Float64Array((N/2+1)*M*M);this.ri=new Float64Array(this.rr.length);this.dr=new Float64Array((N/2+1)*M);this.di=new Float64Array(this.dr.length);this.qr=new Float64Array(this.dr.length);this.qi=new Float64Array(this.dr.length);this.ar=new Float64Array(16);this.ai=new Float64Array(16);this.br=new Float64Array(4);this.bi=new Float64Array(4);this.wr=new Float64Array(4);this.wi=new Float64Array(4);this.p=0;this.op=0;this.samples=0;this.noiseFrames=0;this.calFrames=0;this.method='reference';this.angle=0;this.loading=.01;this.dirty=true;this.fallbacks=0;}
 configure(c){if(c.method!==undefined)this.method=c.method;if(c.angle!==undefined)this.angle=c.angle;if(c.loading!==undefined)this.loading=c.loading;this.dirty=true;}
 calibrate(){this.rr.fill(0);this.ri.fill(0);this.noiseFrames=0;this.calFrames=Math.ceil(FS/H);this.dirty=true;}
 weights(){let t=now();this.fallbacks=0;for(let k=0;k<=N/2;k++){let d=steering(this.angle,k),power=d.reduce((s,x)=>s+x[0]**2+x[1]**2,0),base=k*M,rb=k*M*M;for(let m=0;m<M;m++){this.dr[base+m]=d[m][0];this.di[base+m]=d[m][1];this.qr[base+m]=d[m][0]/power;this.qi[base+m]=-d[m][1]/power;}if(this.method!=='mvdr'||this.noiseFrames===0)continue;let trace=0;for(let m=0;m<M;m++)trace+=this.rr[rb+m*M+m];let load=Math.max(1e-10,this.loading*trace/M);for(let i=0;i<16;i++){this.ar[i]=this.rr[rb+i];this.ai[i]=this.ri[rb+i];}for(let m=0;m<M;m++){this.ar[m*M+m]+=load;this.br[m]=d[m][0];this.bi[m]=d[m][1];}if(!solve(this.ar,this.ai,this.br,this.bi,this.wr,this.wi)){this.fallbacks++;continue;}let den=0;for(let m=0;m<M;m++)den+=d[m][0]*this.wr[m]+d[m][1]*this.wi[m];if(!(den>1e-15)){this.fallbacks++;continue;}for(let m=0;m<M;m++){this.qr[base+m]=this.wr[m]/den;this.qi[base+m]=-this.wi[m]/den;}}this.dirty=false;this.timer.add('weight solve (on change)',t);}
 frame(){let t=now();for(let m=0;m<M;m++){for(let n=0;n<N;n++){this.xr[m][n]=this.history[m][(this.p+n)%N]*this.window[n];this.xi[m][n]=0;}this.fft.run(this.xr[m],this.xi[m]);}this.timer.add('analysis FFT ×4',t);if(this.onSpectrum)this.onSpectrum(this.xr,this.xi);
 if(this.calFrames>0){t=now(); // Discard first N samples after muting: no target leakage into noise statistics.
 if(this.calFrames<=Math.ceil(FS/H)-N/H){this.noiseFrames++;let a=1/this.noiseFrames;for(let k=0;k<=N/2;k++)for(let i=0;i<M;i++)for(let j=0;j<M;j++){let p=k*M*M+i*M+j,re=this.xr[i][k]*this.xr[j][k]+this.xi[i][k]*this.xi[j][k],im=this.xi[i][k]*this.xr[j][k]-this.xr[i][k]*this.xi[j][k];this.rr[p]+=a*(re-this.rr[p]);this.ri[p]+=a*(im-this.ri[p]);}}this.calFrames--;if(this.calFrames===0)this.dirty=true;this.timer.add('noise covariance (calibration)',t);}
 if(this.dirty)this.weights();t=now();for(let k=0;k<=N/2;k++){let re=0,im=0;for(let m=0;m<M;m++){let p=k*M+m;re+=this.qr[p]*this.xr[m][k]-this.qi[p]*this.xi[m][k];im+=this.qr[p]*this.xi[m][k]+this.qi[p]*this.xr[m][k];}for(let e=0;e<2;e++){let m=2*e,p=k*M+m,r=this.method==='reference'?this.xr[m][k]:re*this.dr[p]-im*this.di[p],v=this.method==='reference'?this.xi[m][k]:re*this.di[p]+im*this.dr[p];this.yr[e][k]=r;this.yi[e][k]=(k===0||k===N/2)?0:v;if(k>0&&k<N/2){this.yr[e][N-k]=r;this.yi[e][N-k]=-v;}}}this.timer.add('spatial filtering',t);
 t=now();for(let e=0;e<2;e++){this.fft.run(this.yr[e],this.yi[e],true);for(let n=0;n<N;n++)this.ola[e][(this.op+n)%(2*N)]+=this.yr[e][n]*this.window[n]*.5;}this.timer.add('synthesis IFFT ×2',t);}
 process(input,output){for(let i=0;i<input[0].length;i++){for(let e=0;e<2;e++){output[e][i]=this.ola[e][this.op];this.ola[e][this.op]=0;}for(let m=0;m<M;m++)this.history[m][this.p]=input[m][i];this.p=(this.p+1)%N;this.op=(this.op+1)%(2*N);if(++this.samples%H===0)this.frame();}}
}
